#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"#include "ForsLogic.h"//#include "Resource.h"//#include "MyAvi.h"#pragma comment( lib, "MyAvi.lib" )////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public SPROLOZ  {  int nValue;  //  int nPlay;  char szDir[_MAX_DIR];  MYAVI m_hAvi;  //  } Queue_PolyAvi;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void ClearPolyAvi(SQueue& q,void* s)  {  Queue_PolyAvi* p = (Queue_PolyAvi*)s;  AVI_Close( p->m_hAvi );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~inline void pPtWT( POINT& point, SQueue& q )  {  point.x = int(double(point.x)*q.setScale);  point.y = int(double(point.y)*q.setScale);  point.x -= q.setShift.x;  point.y -= q.setShift.y;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintPolyAvi(DefinePaint)  {  QueueP(Queue_PolyAvi);  //  double dValue = 0;  CShPolyHS& sh = (CShPolyHS&)PipeSH;  //  int nPlay = -1;  if ( IsTypeOK )    {    //CMyPen pen( hDC, RGB(0,0x80,0x80) );    //pen.Rect( p->mRect );    //if ( sh.dKPD >  0. ) nPlay = 0;    //if ( sh.dKPD > 40. ) nPlay = 1;    //if ( sh.dKPD > 70. ) nPlay = 2;		nPlay = sh.SP;    }  //  if ( p->nPlay != nPlay )    {    p->nPlay = nPlay;    AVI_Stop( p->m_hAvi );    if ( nPlay >= 0 )      {      //      char szPath[_MAX_PATH];      sprintf_s( szPath, sizeof(szPath), "%simage%d.avi", p->szDir, nPlay );      DWORD dwAttr = ::GetFileAttributes( szPath );      if ( dwAttr != -1 )        {        if ( p->m_hAvi == NULL )          {          POINT p1 = { p->mRect.left, p->mRect.top };          POINT p2 = { p->mRect.right, p->mRect.bottom };          pPtWT( p1, q );          pPtWT( p2, q );          RECT rect = {p1.x,p1.y,p2.x,p2.y};          p->m_hAvi = AVI_Open( q.hWnd, &rect );          }        if ( p->m_hAvi != NULL )          AVI_Play( p->m_hAvi, szPath, 1, 1 );        }      }    }  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddPolyAvi(DefineTegs)  {  //  AddQueueEx(Queue_PolyAvi);  // Определение функции вывода  p->paint = &PaintPolyAvi;  p->clear = &ClearPolyAvi;  //  char szImage[64];  p->nPlay = -1;  //  STegObj obj[] =    {    { 'S', "image", szImage, 63},    // Дополнительная информация    EXT_QUEUE    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  AddPRSHPipe( def, id_PHS, teg[0].value, p, p->nValue );  //  char szPath[_MAX_PATH],szDrv[_MAX_DRIVE],szFile[_MAX_DIR];  sprintf_s( szFile, sizeof(szFile), "@%s\\ReadMe.txt", szImage );  GetPathScn( szPath, szFile, false );  _splitpath_s( szPath, szDrv, sizeof(szDrv), szFile, sizeof(szFile), 0, 0, 0, 0 );  _makepath_s( p->szDir, sizeof(p->szDir), szDrv, szFile, 0, 0 );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~